"""SW-589 G18: run resolution, holdout/site callers, and the pipeline runner."""
from pathlib import Path


def patch(path: str, swaps: list[tuple[str, str]]) -> None:
    p = Path(path)
    s = p.read_text(encoding="utf8")
    for old, new in swaps:
        assert s.count(old) == 1, (path, old[:70])
        s = s.replace(old, new)
    p.write_text(s, encoding="utf8", newline="")
    print("patched", path)


