def resolve_feature_run(
    base_run: PipelineRun,
    *,
    feature_run_name: str | None = None,
    allow_extract_only: bool = False,
) -> FeatureRun:
    """
    Resolve the feature-set child run to use for training or inspection.

    Falls back to legacy ``features/`` at the base run root when no child runs
    exist yet.

    ``allow_extract_only`` lets readers that only need ``features_all`` (the
    holdout stage, site stability) use an extract-only feature run (SW-589
    G18). Training needs the selected sets, so it leaves this off and gets a
    clear error instead of a run without them.
    """
    if feature_run_name and feature_run_name != "latest":
        named = load_feature_run(base_run, feature_run_name)
        if named.extra.get("extract_only") and not allow_extract_only:
            _refuse_extract_only(named)
        return named

    entries = base_run.extra.get("feature_runs") or []
    if entries:
        for entry in reversed(entries):
            if entry.get("status") != "completed":
                continue
            recorded = entry.get("path")
            if not recorded:
                continue
            candidate = (base_run.run_path / recorded).resolve()
            if entry.get("extract_only"):
                features_all = candidate / FEATURES_DIR_NAME / "features_all.pkl"
                if allow_extract_only and features_all.is_file():
                    return load_feature_run(base_run, recorded)
                continue
            train_path = candidate / FEATURES_DIR_NAME / TRAIN_VALIDATION_SET_NAME
            if train_path.is_file():
                return load_feature_run(base_run, recorded)
''',
