    settings: ModelReportSettings,
    holdout_result: HoldoutResult | None = None,
) -> HoldoutModelReportResult:
    """Cluster- and trace-level confounding reports for one holdout run.

    Reads the run-level ``<level>_level_statistics_<comparison>_<mode>.csv``
    (stacked over holdouts), pools each unit over holdouts and writes one
    Excel + per-model HTML per level under ``<holdout run>/confounding_reports/``.
    """
    patient_levels = [level for level in settings.levels if level not in HOLDOUT_REPORT_LEVELS]
    if patient_levels:
        raise ValueError(
            f"model_reports.levels {patient_levels} are not built from a holdout run; "
            f"use {list(HOLDOUT_REPORT_LEVELS)}"
        )
    holdout_run_dir = resolve_holdout_run_dir(
        run,
        holdout_run_name=settings.holdout_run_name,
        holdout_result=holdout_result,
